import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;

public class SecureDatabaseExample {
    public static void main(String[] args) throws Exception {
        // Connect to the database using DriverManager.getConnection()
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "username", "password");

        // Securely prepare and execute the SQL statement
        String sql = "SELECT * FROM users WHERE username = ?";
        PreparedStatement pstmt = conn.prepareStatement(sql);
        pstmt.setString(1, userInput); // Use parameterized query for security

        // Execute the query
        ResultSet rs = pstmt.executeQuery();

        // Process results as needed
        while (rs.next()) {
            System.out.println(rs.getString("username"));
